new_head='''export const ExpressHttpStreamableMcpServer = (options: ServerOptions, setupCb: (server: McpServer) => void) => {
  // One McpServer per session. An McpServer only holds a single transport at a
  // time, so sharing one across sessions routes every response to the most
  // recently connected client and leaves earlier clients hanging.
  const createServer = () => {
    const server = new McpServer({
      name: options.name,
      version: "1.0.0",
    }, {
      capabilities: {
        logging: {},
        tools: {
          listChanged: false
        }
      }
    });
    setupCb(server);
    return server;
  };

  const app = express();
  app.use(express.json());

  // Liveness endpoint for the hosting platform's health checks.
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok' });
  });
'''
